buggyCode:
final class Account {
    final long id;
    long balance;
    Account(long id, long balance) { this.id = id; this.balance = balance; }
}

static void transfer(Account from, Account to, long amount) {
    synchronized (from) {
        synchronized (to) {
            from.balance -= amount;
            to.balance += amount;
        }
    }
}

Account alice = new Account(1, 1_000_000);
Account bob = new Account(2, 1_000_000);
new Thread(() -> { for (int i = 0; i < 1_000_000; i++) transfer(alice, bob, 1); }, "transfer-1").start();
new Thread(() -> { for (int i = 0; i < 1_000_000; i++) transfer(bob, alice, 1); }, "transfer-2").start();

fix.code:
static void transfer(Account from, Account to, long amount) {
    // Luôn khoá tài khoản id nhỏ hơn trước, bất kể chiều chuyển
    Account first = from.id < to.id ? from : to;
    Account second = from.id < to.id ? to : from;
    synchronized (first) {
        synchronized (second) {
            from.balance -= amount;
            to.balance += amount;
        }
    }
}
